    18→
    19→func NewRepositoryFilesystem(dotGitFs, commonDotGitFs billy.Filesystem) *RepositoryFilesystem {
    20→	return &RepositoryFilesystem{
    21→		dotGitFs:       dotGitFs,
    22→		commonDotGitFs: commonDotGitFs,
    23→	}
    24→}
    25→
    26→func (fs *RepositoryFilesystem) mapToRepositoryFsByPath(path string) billy.Filesystem {
    27→	// Nothing to decide if commondir not defined
    28→	if fs.commonDotGitFs == nil {
    29→		return fs.dotGitFs
    30→	}
    31→
    32→	cleanPath := filepath.Clean(path)
    33→
    34→	// Check exceptions for commondir (https://git-scm.com/docs/gitrepository-layout#Documentation/gitrepository-layout.txt)
    35→	switch cleanPath {
    36→	case fs.dotGitFs.Join(logsPath, "HEAD"):
    37→		return fs.dotGitFs
    38→	case fs.dotGitFs.Join(refsPath, "bisect"), fs.dotGitFs.Join(refsPath, "rewritten"), fs.dotGitFs.Join(refsPath, "worktree"):
    39→		return fs.dotGitFs
    40→	}
    41→
    42→	// Determine dot-git root by first path element.
    43→	// There are some elements which should always use commondir when commondir defined.
    44→	// Usual dot-git root will be used for the rest of files.
    45→	switch strings.Split(cleanPath, string(filepath.Separator))[0] {
    46→	case objectsPath, refsPath, packedRefsPath, configPath, branchesPath, hooksPath, infoPath, remotesPath, logsPath, shallowPath, worktreesPath:
    47→		return fs.commonDotGitFs
    48→	default:
    49→		return fs.dotGitFs
    50→	}
    51→}
