// traceIndexMD5 logs the index file md5 for debugging index corruption.
// TODO: Remove after ENT-242 investigation is complete.
func traceIndexMD5(label string) {
	gitDir, err := exec.CommandContext(context.Background(), "git", "rev-parse", "--git-dir").Output()
	if err != nil {
		return
	}
	indexPath := filepath.Join(strings.TrimSpace(string(gitDir)), "index")
	data, err := os.ReadFile(indexPath)
	if err != nil {
		return
	}
	sum := md5.Sum(data) //nolint:gosec // debug instrumentation
	f, err := os.OpenFile("/tmp/entire-index-trace.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return
	}
	defer f.Close()
	fmt.Fprintf(f, "post-commit %s: %x\n", label, sum)
}

