cmd := runner(ctx, claudePath, "--print", "--output-format", "json", "--model", model, "--setting-sources", "user")

// Isolate the subprocess from the git index to prevent corruption (ENT-242).
// The Claude CLI may perform git operations internally that rewrite the index.
// When running inside a git hook (post-commit), this corrupts the index with
// stale cache-tree entries referencing objects pruned by GC.
tmpIndex, tmpErr := os.CreateTemp("", "entire-summarize-idx-*")
if tmpErr == nil {
	tmpIndex.Close()
	defer os.Remove(tmpIndex.Name())
	cmd.Env = append(os.Environ(), "GIT_INDEX_FILE="+tmpIndex.Name())
}

// Pass prompt via stdin
cmd.Stdin = strings.NewReader(prompt)

var stdout, stderr bytes.Buffer
cmd.Stdout = &stdout
cmd.Stderr = &stderr

err := cmd.Run()

